CREATE TABLE money_operations(id TEXT PRIMARY KEY,actor TEXT NOT NULL,kind TEXT NOT NULL,provider TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('READY','DONE','DECLINED','UNKNOWN','CANCELED')),created INTEGER NOT NULL,detail TEXT NOT NULL,expected REAL,set_balance INTEGER);
CREATE TABLE money_legs(operation TEXT NOT NULL REFERENCES money_operations(id),position INTEGER NOT NULL,player TEXT NOT NULL,delta INTEGER NOT NULL CHECK(typeof(delta)='integer'),state TEXT NOT NULL CHECK(state IN ('PENDING','APPLYING','DONE','DECLINED','UNKNOWN')),PRIMARY KEY(operation,position));
CREATE TABLE money_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,operation TEXT NOT NULL,actor TEXT NOT NULL,message TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE market_deposits(id TEXT PRIMARY KEY,owner TEXT NOT NULL,payload BLOB NOT NULL,label TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('AUCTION','SELL')),price INTEGER NOT NULL CHECK(price>0 AND typeof(price)='integer'),state TEXT NOT NULL CHECK(state IN ('PREPARED','TAGGED','CAPTURED','CANCELED')),created INTEGER NOT NULL,expires INTEGER NOT NULL,provider TEXT NOT NULL);
CREATE TABLE market_listings(id TEXT PRIMARY KEY REFERENCES market_deposits(id),seller TEXT NOT NULL,payload BLOB NOT NULL,label TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0 AND typeof(price)='integer'),expires INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('ACTIVE','RESERVED','SOLD','EXPIRED')),buyer TEXT,operation TEXT,provider TEXT NOT NULL);
CREATE INDEX market_active ON market_listings(state,expires);
CREATE TABLE market_orders(operation TEXT PRIMARY KEY REFERENCES money_operations(id),buyer TEXT NOT NULL,kind TEXT NOT NULL,reference TEXT NOT NULL,payload BLOB,receipt TEXT,state TEXT NOT NULL CHECK(state IN ('RESERVED','DONE','CANCELED')),rotation INTEGER,sku TEXT);
CREATE TABLE market_returns(source TEXT PRIMARY KEY,owner TEXT NOT NULL,payload BLOB NOT NULL,state TEXT NOT NULL CHECK(state IN ('PENDING','DONE')));
CREATE TABLE market_stock(rotation INTEGER NOT NULL,sku TEXT NOT NULL,definition TEXT NOT NULL,PRIMARY KEY(rotation,sku));
CREATE TABLE market_limits(rotation INTEGER NOT NULL,sku TEXT NOT NULL,player TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(rotation,sku,player));
